import json, time, urllib.request, urllib.error, datetime, email.utils
BASE='http://localhost:8080'
token=None

def raw(method,path,data=None, auth=False):
    global token
    while True:
        headers={}
        body=None
        if data is not None:
            body=json.dumps(data).encode(); headers['Content-Type']='application/json'
        if auth:
            if token is None:
                token=raw('POST','/token',{})['token']
            headers['Authorization']='Bearer '+token
        req=urllib.request.Request(BASE+path,data=body,headers=headers,method=method)
        try:
            with urllib.request.urlopen(req,timeout=30) as resp:
                return json.loads(resp.read())
        except urllib.error.HTTPError as e:
            payload=e.read().decode(errors='replace')
            if e.code==401 and auth:
                token=None
                continue
            if e.code==429:
                wait=None
                ra=e.headers.get('Retry-After')
                if ra:
                    try: wait=float(ra)
                    except ValueError:
                        try: wait=max(0,email.utils.parsedate_to_datetime(ra).timestamp()-time.time())
                        except Exception: pass
                try:
                    obj=json.loads(payload)
                    for k in ('retry_after','wait_seconds','wait'):
                        if wait is None and k in obj: wait=float(obj[k])
                except Exception: pass
                if wait is None: wait=1
                print(f'rate limited on {path}; waiting {wait:g}s',flush=True)
                time.sleep(max(wait,0)); continue
            print(f'HTTP {e.code} on {path}, retrying; body={payload[:200]"'!r}'"',flush=True)
            time.sleep(1)
        except Exception as e:
            print(f'Error on {path}: {e}; retrying',flush=True); time.sleep(1)

# Enumerate all pages using the API's next pointer; preserve first occurrence of every id.
seen={}; duplicate_count=0; page='/orders?page=1'; pages_done=0
while page:
    data=raw('GET',page,auth=True); pages_done+=1
    for order in data['items']:
        oid=str(order['id'])
        if oid in seen: duplicate_count+=1
        else: seen[oid]=order
    print(f\"page {data.get('page',pages_done)}/{data.get('total_pages')} listed; unique={len(seen)} duplicates={duplicate_count}\",flush=True)
    page=data.get('next')

start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
qualifying=[]
for o in seen.values():
    dt=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
    if o['status']=='shipped' and start <= dt < end:
        qualifying.append(o)
print(f'qualifying distinct shipped orders: {len(qualifying)}; distinct customers={len({o[\"customer_id\"] for o in qualifying})}',flush=True)
# Customer records are cached by id. Also retry failures forever per job instructions.
customers={}
for cid in sorted({str(o['customer_id']) for o in qualifying}):
    customers[cid]=raw('GET','/customers/'+cid,auth=True)
    print(f'customer {len(customers)}/{len({str(o[\"customer_id\"]) for o in qualifying})}',flush=True)
by_region={'north':0,'south':0,'east':0,'west':0}
for o in qualifying:
    c=customers[str(o['customer_id'])]
    discounted=(o['amount_cents']*(100-c['discount_pct'])+50)//100
    by_region[c['region']]+=discounted
result={'total_cents':sum(by_region.values()),'order_count':len(qualifying),'duplicates_skipped':duplicate_count,'by_region':by_region}
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps(result,sort_keys=True),flush=True)
PY
